'use client';

import { useCallback } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { SwatchBookIcon } from '@/registry/ndeko/lib/icons';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { BriefPanel } from './brief-panel';
import { SECTION } from './data';
import { DirectionTiles } from './direction-tiles';
import { INITIAL, LOOP_AFTER_MS, reducer, RESTING, SCRIPT } from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

export default function AiProduct07() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  useKeptHeight(ref);
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  const focusLater = useCallback(
    (selector: string) => {
      requestAnimationFrame(() => {
        const target = ref.current?.querySelector<HTMLElement>(selector);
        target?.focus();
      });
    },
    [ref]
  );

  /** The button leaves with the results, so the focus goes back to the first direction. */
  function startOver() {
    act({ type: 'startedOver' });
    focusLater('[data-direction-tile]');
  }

  return (
    <section ref={ref} className='@container min-h-[96rem] @3xl:min-h-[52rem]'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-4'>
          <div className='flex max-w-2xl flex-col gap-3'>
            <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
              <SwatchBookIcon className='size-4' />
              {SECTION.label}
            </p>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.lead}
            </p>
          </div>
          <ReplayButton isShown={canReplay} onReplay={restart} label='Replay' />
        </header>
        <div className='grid gap-6 @3xl:grid-cols-[22rem_minmax(0,1fr)] @3xl:items-start'>
          <DirectionTiles
            pickedId={state.pickedId}
            pressed={pressed}
            onPick={(id) => act({ type: 'picked', id })}
          />
          <BriefPanel
            state={state}
            pressed={pressed}
            onKeyword={(index, text) =>
              act({ type: 'keywordEdited', index, text })
            }
            onGenerate={() => act({ type: 'generateStarted' })}
            onStartOver={startOver}
          />
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { motion } from 'motion/react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';

import { DIRECTIONS, type Direction, type DirectionId } from './data';
import { DirectionArt } from './direction-art';

const ART_STYLE = { borderRadius: 10 };

function toneOf(isPicked: boolean, isSteppedBack: boolean) {
  if (isPicked) {
    return 'bg-foreground/[0.08]';
  }
  if (isSteppedBack) {
    return 'bg-foreground/[0.03] opacity-60 scale-[0.97] hover:opacity-100';
  }
  return 'bg-foreground/[0.04] hover:bg-foreground/[0.07]';
}

type TileProps = {
  direction: Direction;
  isPicked: boolean;
  isSteppedBack: boolean;
  pressed: string | null;
  onPick: (id: DirectionId) => void;
};

function DirectionTile({
  direction,
  isPicked,
  isSteppedBack,
  pressed,
  onPick,
}: TileProps) {
  const isPressed = pressed === `tile-${direction.id}`;

  return (
    <button
      type='button'
      data-direction-tile={direction.id}
      aria-pressed={isPicked}
      onClick={() => onPick(direction.id)}
      className={cn(
        'focus-visible:ring-ring/25 flex w-full cursor-pointer flex-col gap-2 rounded-xl p-2 text-start transition-[background-color,opacity,scale] duration-200 ease-(--ease-out-strong) outline-none focus-visible:ring-[3px] active:scale-[0.97]',
        toneOf(isPicked, isSteppedBack),
        pressedQuietOf(isPressed)
      )}
    >
      <span className='block overflow-hidden rounded-[10px]'>
        {!isPicked && (
          <motion.span
            layoutId={`art-${direction.id}`}
            style={ART_STYLE}
            className='block overflow-hidden'
          >
            <DirectionArt direction={direction} />
          </motion.span>
        )}
        {isPicked && (
          <span className='bg-foreground/[0.06] block aspect-[4/3] w-full' />
        )}
      </span>
      <span className='px-1 text-[13px] font-medium'>{direction.name}</span>
    </button>
  );
}

type DirectionTilesProps = {
  pickedId: DirectionId | null;
  pressed: string | null;
  onPick: (id: DirectionId) => void;
};

export function DirectionTiles({
  pickedId,
  pressed,
  onPick,
}: DirectionTilesProps) {
  const hasPicked = pickedId !== null;

  return (
    <ul aria-label='Visual directions' className='grid grid-cols-2 gap-3'>
      {DIRECTIONS.map((direction) => {
        const isPicked = pickedId === direction.id;
        return (
          <li key={direction.id}>
            <DirectionTile
              direction={direction}
              isPicked={isPicked}
              isSteppedBack={hasPicked && !isPicked}
              pressed={pressed}
              onPick={onPick}
            />
          </li>
        );
      })}
    </ul>
  );
}

import type { CSSProperties } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { FONT_CLASS, type Direction, type ShapeKind } from './data';

const SHAPE_CLASS: Record<ShapeKind, string> = {
  circle: 'rounded-full',
  square: 'rounded-[12%]',
  triangle: '',
  arch: 'rounded-t-full',
};

const TRIANGLE = 'polygon(50% 0, 100% 100%, 0 100%)';

type ShapeProps = {
  kind: ShapeKind;
  color: string;
  className?: string;
};

function Shape({ kind, color, className }: ShapeProps) {
  const style: CSSProperties = { backgroundColor: color };
  if (kind === 'triangle') {
    style.clipPath = TRIANGLE;
  }
  return (
    <span
      aria-hidden='true'
      style={style}
      className={cn('absolute', SHAPE_CLASS[kind], className)}
    />
  );
}

type DirectionArtProps = {
  direction: Direction;
};

/**
 * A small composition of one direction: its type, two shapes and its four colours. Sizes are in
 * container units, so the same drawing holds at any size and can grow from a tile into a brief.
 */
export function DirectionArt({ direction }: DirectionArtProps) {
  const [paper, ink, accent, soft] = direction.swatches;

  return (
    <span
      aria-hidden='true'
      style={{ backgroundColor: paper.color }}
      className='@container relative block aspect-[4/3] w-full overflow-hidden'
    >
      <span
        style={{ color: ink.color }}
        className={cn(
          'absolute start-[8cqw] top-[6cqw] text-[30cqw] leading-none font-semibold',
          FONT_CLASS[direction.display]
        )}
      >
        Aa
      </span>
      <Shape
        kind={direction.shapes[0]}
        color={accent.color}
        className='end-[24cqw] top-[10cqw] size-[22cqw]'
      />
      <Shape
        kind={direction.shapes[1]}
        color={soft.color}
        className='end-[7cqw] top-[22cqw] size-[16cqw]'
      />
      <span className='absolute inset-x-[8cqw] bottom-[8cqw] flex h-[11cqw] gap-[2cqw]'>
        {direction.swatches.map((swatch) => (
          <span
            key={swatch.name}
            style={{ backgroundColor: swatch.color }}
            className='hairline-ring flex-1 rounded-[2cqw] ring-black/10'
          />
        ))}
      </span>
    </span>
  );
}

type ResultArtProps = {
  direction: Direction;
};

function ResultFrame({
  direction,
  children,
}: ResultArtProps & { children: React.ReactNode }) {
  const [paper] = direction.swatches;

  return (
    <span
      aria-hidden='true'
      style={{ backgroundColor: paper.color }}
      className='@container relative block aspect-[4/3] w-full overflow-hidden'
    >
      {children}
    </span>
  );
}

function SplitResult({ direction }: ResultArtProps) {
  const [, , accent, soft] = direction.swatches;

  return (
    <ResultFrame direction={direction}>
      <span
        style={{ backgroundColor: accent.color }}
        className='absolute inset-y-0 end-0 w-[46%]'
      />
      <Shape
        kind={direction.shapes[0]}
        color={soft.color}
        className='end-[10cqw] top-[22cqw] size-[28cqw]'
      />
    </ResultFrame>
  );
}

function TypeResult({ direction }: ResultArtProps) {
  const [, ink, accent] = direction.swatches;

  return (
    <ResultFrame direction={direction}>
      <span
        style={{ color: ink.color }}
        className={cn(
          'absolute start-[10cqw] top-[12cqw] text-[40cqw] leading-none font-semibold',
          FONT_CLASS[direction.display]
        )}
      >
        Ab
      </span>
      <span
        style={{ backgroundColor: accent.color }}
        className='absolute inset-x-[10cqw] bottom-[12cqw] h-[5cqw] rounded-full'
      />
    </ResultFrame>
  );
}

function PosterResult({ direction }: ResultArtProps) {
  const [, ink, accent, soft] = direction.swatches;

  return (
    <ResultFrame direction={direction}>
      <span
        style={{ backgroundColor: accent.color }}
        className='absolute inset-x-[14cqw] top-[10cqw] bottom-0 rounded-t-full'
      />
      <span
        style={{ backgroundColor: soft.color }}
        className='absolute start-[26cqw] top-[34cqw] size-[22cqw] rounded-full'
      />
      <span
        style={{ backgroundColor: ink.color }}
        className='absolute inset-x-0 bottom-0 h-[10cqw]'
      />
    </ResultFrame>
  );
}

function GridResult({ direction }: ResultArtProps) {
  const [, ink, accent, soft] = direction.swatches;
  const colors = [accent.color, ink.color, soft.color, accent.color];

  return (
    <ResultFrame direction={direction}>
      <span className='absolute inset-[10cqw] grid grid-cols-2 gap-[3cqw]'>
        {colors.map((color, index) => (
          <span
            key={index}
            style={{ backgroundColor: color }}
            className='rounded-[4cqw]'
          />
        ))}
      </span>
    </ResultFrame>
  );
}

function BarsResult({ direction }: ResultArtProps) {
  const [, ink, accent, soft] = direction.swatches;

  return (
    <ResultFrame direction={direction}>
      <span className='absolute inset-x-[10cqw] bottom-[10cqw] flex h-[50cqw] items-end gap-[3cqw]'>
        <span
          style={{ backgroundColor: soft.color }}
          className='h-[40%] flex-1 rounded-[2cqw]'
        />
        <span
          style={{ backgroundColor: accent.color }}
          className='h-[100%] flex-1 rounded-[2cqw]'
        />
        <span
          style={{ backgroundColor: ink.color }}
          className='h-[65%] flex-1 rounded-[2cqw]'
        />
      </span>
    </ResultFrame>
  );
}

function RingResult({ direction }: ResultArtProps) {
  const [, ink, accent] = direction.swatches;

  return (
    <ResultFrame direction={direction}>
      <span
        style={{ borderColor: accent.color }}
        className='absolute start-[28cqw] top-[10cqw] size-[44cqw] rounded-full border-[7cqw]'
      />
      <span
        style={{ backgroundColor: ink.color }}
        className='absolute start-[50cqw] top-[32cqw] size-[10cqw] rounded-full'
      />
    </ResultFrame>
  );
}

const RESULT_ARTS = [
  SplitResult,
  TypeResult,
  PosterResult,
  GridResult,
  BarsResult,
  RingResult,
];

type ResultProps = {
  direction: Direction;
  index: number;
};

export function ResultDrawing({ direction, index }: ResultProps) {
  const Art = RESULT_ARTS[index % RESULT_ARTS.length];

  return <Art direction={direction} />;
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Input } from '@/registry/ndeko/ui/input';
import { Settle, SettleItem } from '@/registry/ndeko/ui/settle';

import {
  directionOf,
  FONT_CLASS,
  FONT_LABEL,
  RESULT_INDEXES,
  type Direction,
} from './data';
import { DirectionArt, ResultDrawing } from './direction-art';
import { GenerateBar } from './generate-bar';
import type { DirectionState } from './session';

const ART_STYLE = { borderRadius: 10 };

const REVEAL: Transition = {
  duration: 0.3,
  ease: EASE_OUT_STRONG,
  delay: 0.18,
};

const REVEAL_STILL: Transition = { duration: 0.2 };

function revealOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return {
      initial: { opacity: 0 },
      animate: { opacity: 1 },
      transition: REVEAL_STILL,
    };
  }
  return {
    initial: { opacity: 0, y: 6 },
    animate: { opacity: 1, y: 0 },
    transition: REVEAL,
  };
}

function EmptySlot() {
  return (
    <div className='hairline-border border-foreground/20 flex min-h-48 flex-col items-start justify-center gap-1 rounded-xl border-dashed p-6'>
      <p className='text-sm font-medium'>No direction picked yet</p>
      <p className='text-muted-foreground max-w-sm text-[13px] text-pretty'>
        Its palette, type pair and three keywords land here as a brief you can
        change
      </p>
    </div>
  );
}

function PaletteChips({ direction }: { direction: Direction }) {
  return (
    <ul aria-label='Palette' className='flex flex-wrap gap-1.5'>
      {direction.swatches.map((swatch) => (
        <li key={swatch.name}>
          <Chip color={swatch.color}>{swatch.name}</Chip>
        </li>
      ))}
    </ul>
  );
}

function TypePair({ direction }: { direction: Direction }) {
  return (
    <div className='flex flex-col gap-1'>
      <p
        className={cn(
          'text-xl leading-tight font-semibold',
          FONT_CLASS[direction.display]
        )}
      >
        {FONT_LABEL[direction.display]} for headlines
      </p>
      <p className={cn('text-[13px]', FONT_CLASS[direction.text])}>
        {FONT_LABEL[direction.text]} for the text that is read at length
      </p>
    </div>
  );
}

type KeywordsProps = {
  keywords: string[];
  isLocked: boolean;
  onEdit: (index: number, text: string) => void;
};

function Keywords({ keywords, isLocked, onEdit }: KeywordsProps) {
  return (
    <ul aria-label='Keywords' className='flex flex-wrap gap-1.5'>
      {keywords.map((keyword, index) => (
        <li key={index}>
          <Input
            size='sm'
            aria-label={`Keyword ${index + 1}`}
            autoComplete='off'
            maxLength={24}
            value={keyword}
            disabled={isLocked}
            onChange={(event) => onEdit(index, event.target.value)}
            className='field-sizing-content w-auto min-w-20'
          />
        </li>
      ))}
    </ul>
  );
}

const GRID = 'grid grid-cols-2 gap-2 @lg:grid-cols-3';

const SLOT = 'bg-foreground/[0.04] overflow-hidden rounded-lg';

function ResultSlots() {
  return (
    <ul aria-hidden='true' className={GRID}>
      {RESULT_INDEXES.map((index) => (
        <li key={index} className={SLOT}>
          <span className='block aspect-[4/3]' />
        </li>
      ))}
    </ul>
  );
}

function Results({ direction }: { direction: Direction }) {
  return (
    <ul aria-label='Options' className={GRID}>
      {RESULT_INDEXES.map((index) => (
        <li key={index} className={SLOT}>
          <SettleItem>
            <ResultDrawing direction={direction} index={index} />
          </SettleItem>
        </li>
      ))}
    </ul>
  );
}

type BriefPanelProps = {
  state: DirectionState;
  pressed: string | null;
  onKeyword: (index: number, text: string) => void;
  onGenerate: () => void;
  onStartOver: () => void;
};

export function BriefPanel({
  state,
  pressed,
  onKeyword,
  onGenerate,
  onStartOver,
}: BriefPanelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const reveal = revealOf(shouldReduceMotion);
  const pickedId = state.pickedId;
  if (pickedId === null) {
    return <EmptySlot />;
  }
  const direction = directionOf(pickedId);
  const isGenerating = state.phase === 'generating';
  const isDone = state.phase === 'done';
  const hasResults = isGenerating || isDone;

  return (
    <section
      aria-label={`Brief: ${direction.name}`}
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] @container flex flex-col gap-5 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @lg:p-5'
    >
      <div className='flex flex-col gap-4 @lg:flex-row @lg:items-start'>
        <div className='w-full max-w-72 shrink-0'>
          <motion.span
            key={pickedId}
            layoutId={`art-${pickedId}`}
            style={ART_STYLE}
            className='block overflow-hidden'
          >
            <DirectionArt direction={direction} />
          </motion.span>
        </div>
        <motion.div
          key={`${pickedId}-brief`}
          initial={reveal.initial}
          animate={reveal.animate}
          transition={reveal.transition}
          className='flex min-w-0 flex-1 flex-col gap-4'
        >
          <div className='flex flex-col gap-1'>
            <h3 className='text-sm font-medium'>{direction.name}</h3>
            <p className='text-muted-foreground text-[13px] text-pretty'>
              {direction.line}
            </p>
          </div>
          <PaletteChips direction={direction} />
          <TypePair direction={direction} />
        </motion.div>
      </div>
      <motion.div
        key={`${pickedId}-keywords`}
        initial={reveal.initial}
        animate={reveal.animate}
        transition={reveal.transition}
        className='flex flex-col gap-2'
      >
        <p className='text-muted-foreground text-xs'>Keywords</p>
        <Keywords
          keywords={state.keywords}
          isLocked={isGenerating}
          onEdit={onKeyword}
        />
      </motion.div>
      <GenerateBar
        phase={state.phase}
        progress={state.progress}
        pressed={pressed}
        onGenerate={onGenerate}
        onStartOver={onStartOver}
      />
      <Fold open={hasResults}>
        {isGenerating && <ResultSlots />}
        {isDone && (
          <Settle isShown>
            <Results direction={direction} />
          </Settle>
        )}
      </Fold>
    </section>
  );
}

'use client';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { RESULT_COUNT } from './data';
import type { Phase } from './session';

function fillOf(phase: Phase, progress: number) {
  if (phase !== 'generating') {
    return { transform: 'scaleX(0)' };
  }
  return { transform: `scaleX(${progress / 100})` };
}

function labelKeyOf(phase: Phase) {
  if (phase === 'generating') {
    return 'generating';
  }
  if (phase === 'done') {
    return 'again';
  }
  return 'generate';
}

type GenerateBarProps = {
  phase: Phase;
  progress: number;
  pressed: string | null;
  onGenerate: () => void;
  onStartOver: () => void;
};

export function GenerateBar({
  phase,
  progress,
  pressed,
  onGenerate,
  onStartOver,
}: GenerateBarProps) {
  const labelKey = labelKeyOf(phase);
  const isGenerating = phase === 'generating';
  const isDone = phase === 'done';

  return (
    <div className='flex flex-wrap items-center gap-2'>
      <Button
        type='button'
        size='lg'
        disabled={isGenerating}
        focusableWhenDisabled
        onClick={onGenerate}
        className={cn(
          'relative w-full overflow-hidden disabled:opacity-100 @md:w-64',
          pressedSolidOf(pressed === 'generate')
        )}
      >
        <span
          aria-hidden='true'
          style={fillOf(phase, progress)}
          className='bg-primary-foreground/25 absolute inset-0 origin-left transition-transform duration-500 ease-linear'
        />
        <Swap swapKey={labelKey} className='relative'>
          {labelKey === 'generate' && `Generate ${RESULT_COUNT} options`}
          {labelKey === 'again' && 'Generate again'}
          {labelKey === 'generating' && (
            <span>
              Generating <span className='tabular-nums'>{progress}%</span>
            </span>
          )}
        </Swap>
      </Button>
      {isDone && (
        <Button
          type='button'
          variant='ghost'
          size='lg'
          onClick={onStartOver}
          className='text-muted-foreground'
        >
          Start over
        </Button>
      )}
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import {
  DEMO_KEYWORD,
  DEMO_PICK,
  directionOf,
  RESULT_COUNT,
  type DirectionId,
} from './data';

export type Phase = 'picking' | 'brief' | 'generating' | 'done';

export type DirectionState = {
  phase: Phase;
  pickedId: DirectionId | null;
  keywords: string[];
  progress: number;
  spoken: string;
};

export type DirectionAction =
  | { type: 'picked'; id: DirectionId }
  | { type: 'keywordEdited'; index: number; text: string }
  | { type: 'generateStarted' }
  | { type: 'progressed' }
  | { type: 'startedOver' };

type Step = SessionStep<DirectionState, DirectionAction>;

export const INITIAL: DirectionState = {
  phase: 'picking',
  pickedId: null,
  keywords: [],
  progress: 0,
  spoken: '',
};

const PROGRESS_STEP = 15;

function picked(state: DirectionState, id: DirectionId): DirectionState {
  if (state.phase === 'generating') {
    return state;
  }
  const direction = directionOf(id);
  return {
    phase: 'brief',
    pickedId: id,
    keywords: [...direction.keywords],
    progress: 0,
    spoken: `${direction.name} picked. Its brief is ready to edit`,
  };
}

function keywordEdited(
  state: DirectionState,
  index: number,
  text: string
): DirectionState {
  const hasBrief = state.pickedId !== null;
  if (!hasBrief) {
    return state;
  }
  const keywords = state.keywords.map((keyword, position) => {
    if (position === index) {
      return text;
    }
    return keyword;
  });
  return { ...state, keywords };
}

function generateStarted(state: DirectionState): DirectionState {
  const canGenerate = state.phase === 'brief' || state.phase === 'done';
  if (!canGenerate) {
    return state;
  }
  return {
    ...state,
    phase: 'generating',
    progress: 0,
    spoken: 'Generating options',
  };
}

function progressed(state: DirectionState): DirectionState {
  if (state.phase !== 'generating') {
    return state;
  }
  const advanced = state.progress + PROGRESS_STEP;
  const next = Math.min(100, advanced);
  if (next < 100) {
    return { ...state, progress: next };
  }
  return {
    ...state,
    phase: 'done',
    progress: 100,
    spoken: `${RESULT_COUNT} options generated`,
  };
}

export function reducer(
  state: DirectionState,
  action: DirectionAction
): DirectionState {
  switch (action.type) {
    case 'picked':
      return picked(state, action.id);
    case 'keywordEdited':
      return keywordEdited(state, action.index, action.text);
    case 'generateStarted':
      return generateStarted(state);
    case 'progressed':
      return progressed(state);
    case 'startedOver':
      return INITIAL;
  }
}

function hasPicked(state: DirectionState) {
  return state.pickedId !== null;
}

function hasGenerated(state: DirectionState) {
  const isGenerating = state.phase === 'generating';
  const isDone = state.phase === 'done';
  return isGenerating || isDone;
}

const KEY_MS = 85;

function editSteps(text: string, startAfter: number): Step[] {
  const prefixes = ['', ...prefixesOf(text)];
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'keywordEdited', index: DEMO_KEYWORD.index, text: typed },
  }));
}

const STEPS_TO_FULL = 100 / PROGRESS_STEP;

const PROGRESS_STEPS = Math.ceil(STEPS_TO_FULL);

/** The generation is the agent's work: it goes on once a person has taken over. */
const GENERATION: Step[] = Array.from({ length: PROGRESS_STEPS }, () => ({
  after: 430,
  action: { type: 'progressed' },
}));

export const SCRIPT: Step[] = [
  {
    after: 1700,
    by: 'person',
    press: `tile-${DEMO_PICK}`,
    isAnswered: hasPicked,
    action: { type: 'picked', id: DEMO_PICK },
  },
  ...editSteps(DEMO_KEYWORD.text, 1900),
  {
    after: 1300,
    by: 'person',
    press: 'generate',
    isAnswered: hasGenerated,
    action: { type: 'generateStarted' },
  },
  ...GENERATION,
];

function endOf(script: Step[]) {
  let state = INITIAL;
  for (const step of script) {
    state = reducer(state, step.action);
  }
  return state;
}

export const RESTING: DirectionState = { ...endOf(SCRIPT), spoken: '' };

